cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv1d_fp16_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    half* __restrict__ output,
    int batch,
    int in_c,
    int out_c,
    int length,
    int kernel_size,
    int length_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * out_c * length_out;
    if (idx >= total) return;

    int pos = idx % length_out;                         // output position
    int oc  = (idx / length_out) % out_c;               // output channel
    int b   = idx / (out_c * length_out);               // batch index

    float acc = 0.0f;
    for (int ic = 0; ic < in_c; ++ic) {
        for (int k = 0; k < kernel_size; ++k) {
            int in_idx = ((b * in_c + ic) * length) + (pos + k);
            int w_idx  = ((oc * in_c + ic) * kernel_size) + k;
            acc += __half2float(input[in_idx]) * __half2float(weight[w_idx]);
        }
    }
    if (bias != nullptr) {
        acc += __half2float(bias[oc]);
    }
    output[idx] = __float2half(acc);
}

torch::Tensor conv1d_fp16_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias)
{
    const int batch       = input.size(0);
    const int in_c        = input.size(1);
    const int length      = input.size(2);
    const int out_c       = weight.size(0);
    const int kernel_size = weight.size(2);
    const int length_out  = length - kernel_size + 1;

    auto output = torch::empty({batch, out_c, length_out},
                               input.options());

    const int threads = 256;
    const int total   = batch * out_c * length_out;
    const int blocks  = (total + threads - 1) / threads;

    conv1d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const half*>(input.data_ptr()),
        reinterpret_cast<const half*>(weight.data_ptr()),
        bias.defined() ? reinterpret_cast<const half*>(bias.data_ptr()) : nullptr,
        reinterpret_cast<half*>(output.data_ptr()),
        batch,
        in_c,
        out_c,
        length,
        kernel_size,
        length_out);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in conv1d_fp16_forward: %s\\n", cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &conv1d_fp16_forward, "FP16 Conv1d forward (CUDA)");
}
'''

